from typing import Generic, Optional, TypeVar, Union

T = TypeVar('T')

class Result(Generic[T]):
    def __init__(self, value: Optional[T] = None, error: Union[str, None] = None):
        self.value = value
        self.error = error

def add(a: float, b: float) -> float:
    return a + b

